def async_run(prog, args):
    pid = os.fork()
    if pid:
        os.waitpid(pid, 0)
    else:
        dpid = os.fork()
        if not dpid:
            os.system(" ".join([prog] + args))
        os._exit(0)

func_after:
def async_run(self, args):
    pid = os.fork()
    if pid:
        os.waitpid(pid, 0)
    else:
        dpid = os.fork()
        if not dpid:
            self.debug_log("Running %s" % " ".join(pipes.quote(a)
                                                   for a in args))
            proc = Popen(args, stdin=PIPE, stdout=PIPE, stderr=PIPE)
            (out, err) = proc.communicate()
            rv = proc.wait()
            if rv != 0:
                self.logger.error("Trigger: Error running %s (%s): %s" %
                                  (args[0], rv, err))
            elif err:
                self.debug_log("Trigger: Error: %s" % err)
        os._exit(0)

def set_user_password(self, context, user_id, user):
    user_ref = self.update_user(context, user_id, user)
    try:
        for token_id in self.token_api.list_tokens(context, user_id):
            self.token_api.delete_token(context, token_id)
    except exception.NotImplemented:
        # The password has been changed but tokens remain valid for
        # backends that can't list tokens for users
        LOG.warning('Password changed for %s, but existing tokens remain '
                    'valid' % user_id)
    return user_ref

