def is_authenticated(self, user, password):
    # The content of the file is not cached because reading is generally a
    # very cheap operation, and it's useful to get live updates of the
    # htpasswd file.
    with open(self.filename) as fd:
        for line in fd:
            line = line.strip()
            if line:
                login, hash_value = line.split(":")
                if login == user:
                    return self.verify(hash_value, password)
    return False

def constructObject(data):
    try:
        classBase = eval(data[""] + "." + data[""].title())
    except NameError:
        logger.error("Don't know how to handle message type: \"%s\"", data[""])
        return None
    try:
        returnObj = classBase()
        returnObj.decode(data)
    except KeyError as e:
        logger.error("Missing mandatory key %s", e)
        return None
    except:
        logger.error("classBase fail", exc_info=True)
        return None
    else:
        return returnObj

