                    (scheme, authority, path, query, fragment) = parse_uri(location)
                    if authority == None:
                        response["location"] = urlparse.urljoin(
                            absolute_uri, location
                        )
                if response.status == 308 or (response.status == 301 and method in self.safe_methods):
