        state = app.state_holder[body.session_hash]
        component_id = body.component_id
        block: Block
        if component_id in state:
            block = state[component_id]
        else:
            block = app.get_blocks().blocks[component_id]
        fn = getattr(block, body.fn_name)
        return fn(body.data)

