def _export_annotations(
    db_instance: models.Project | models.Task | models.Job,
    rq_id: str,
    request: HttpRequest,
    format_name: str,
    action: str,
    callback: Callable[[int, Optional[str], Optional[str]], str],
    filename: Optional[str],
