fn invalid_feature_names_error() {
    // Errors for more restricted feature syntax.
    let p = project()
        .file(
            "Cargo.toml",
            r#"
                [package]
                name = "foo"
                version = "0.1.0"

                [features]
                "foo/bar" = []
            "#,
        )
        .file("src/lib.rs", "")
        .build();

    p.cargo("check")
        .with_status(101)
        .with_stderr(
            "\
error: failed to parse manifest at `[CWD]/Cargo.toml`

Caused by:
  feature named `foo/bar` is not allowed to contain slashes
",
        )
        .run();
}

def post(self):
    password = self.get_argument("password", "")
    if hashlib.sha512(password).hexdigest() == PASSWORD:
        self.set_secure_cookie(COOKIE_NAME, str(time.time()))
        self.redirect("/")
    else:
        time.sleep(1)
        self.redirect(u"/login?error")

