                slide_id, traverse_obj(slide, ('image', 'name')),
                traverse_obj(slide, ('image', 'extname'), default=slide_ext_default),
                int_or_none(slide.get('time'), scale=1000)))

    if not slides and player_info.get('slides_xml_url'):
