def clone(
    self,
    pdf_dest: PdfWriterProtocol,
    force_duplicate: bool = False,
    ignore_fields: Optional[Sequence[Union[str, int]]] = (),
) -> "DictionaryObject":
    """Clone object into pdf_dest."""
    try:
        if self.indirect_reference.pdf == pdf_dest and not force_duplicate:  # type: ignore
            return self
    except Exception:
        pass

