                for key in ('note', 'html', 'raw html', 'min', 'max', 'minlength', 'maxlength', 'step', 'scale', 'inline', 'inline width', 'currency symbol', 'pen color', 'file css class'):  # 'script', 'css',
                    if key in field.extras:
                        if key not in extras:
                            extras[key] = {}
                        if skip_undefined:
                            try:
                                extras[key][field.number] = field.extras[key].text(user_dict).strip()
                            except LazyNameError:
                                raise
                            except Exception as err:
                                if self.interview.debug:
                                    logmessage("Exception in review block: " + err.__class__.__name__ + ": " + str(err))
