                                the_func(0)
                            elif field.datatype in ('text', 'password', 'email'):
                                the_func('')
                            elif field.datatype == 'date':
                                the_func('01/01/1970')
                            elif field.datatype == 'time':
                                the_func('12:00 AM')
                            elif field.datatype == 'datetime':
                                the_func('01/01/1970 12:00 AM')
