                        if isinstance(extras[key][field.number], str):
                            extras[key][field.number] = extras[key][field.number].strip()
                            if extras[key][field.number] == '':
                                del extras[key][field.number]
            if hasattr(field, 'helptext'):
                if skip_undefined:
