            var changed = false;
            $(elem).find('option').each(function(){
              var thisVal = daVarLookupOption[$(this).val()];
              var oldVal = $(this).prop('selected') == true;
              var newVal = false;
              for (var i = 0; i < n; ++i){
                if (thisVal == theValue[i]){
                  newVal = true;
                }
              }
              if (newVal !== oldVal){
                changed = true;
                $(this).prop('selected', newVal);
              }
            });
            if (changed){
              $(elem).trigger('change');
            }
          }
        }
        else{
          if ($(elem).val() != theValue){
            $(elem).val(theValue);
            $(elem).trigger('change');
          }
        }
