            $(elem).find('option').each(function(){
              if ($(this).prop('selected')){
                if (daVarLookupOption[$(this).val()]){
                  selectedVals.push(daVarLookupOption[$(this).val()]);
                }
              }
            });
            return selectedVals;
          }
        }
        else if ($(elem).prop('tagName') == "SELECT" && $(elem).hasClass('daobject')){
          theVal = atou($(elem).val());
        }
        else{
          theVal = $(elem).val();
        }
        return theVal;
      }
