        if ($(elem).prop('tagName') != "SELECT"){
          console.log("setField: field " + fieldName + " is not a dropdown field");
          return;
        }
        var oldVal = $(elem).val();
        $(elem).find("option[value!='']").each(function(){
          $(this).remove();
        });
        var n = choices.length;
        for (var i = 0; i < n; i++){
          var opt = $("<option>");
