        if (forgetPrior){
          args = {_action: action, _arguments: args};
          action = '_da_priority_action';
        }
        var data = {action: action, arguments: args};
        daSpinnerTimeout = setTimeout(daShowSpinner, 1000);
        return $.ajax({
          type: "POST",
