      function atou(b64) {
        return decodeURIComponent(escape(atob(b64)));
      }
      function utoa(data) {
        return btoa(unescape(encodeURIComponent(data)));
      }
      function dabtoa(str) {
        return utoa(str).replace(/[\\n=]/g, '');
      }
      function daatob(str) {
        return atou(str);
