def exists_path_from(
    self,
    src_tuple: Tuple[int, int],
    target_tuple: Tuple[int, int],
) -> bool:
    """Checks if there is a path between the source chain ID/sequence and
    target chain ID/sequence.
    """
    src_chain, src_seq = src_tuple
    target_chain, target_seq = target_tuple

    if src_chain == target_chain:
        return target_seq <= src_seq

    # We have to graph traverse the links to check for indirect paths.
    visited_chains = collections.Counter()
    search = [(src_chain, src_seq)]
    while search:
        chain, seq = search.pop()
        visited_chains[chain] = max(seq, visited_chains[chain])
        for tc, links in self.maps.get(chain, {}).items():
            for ss, ts in links.items():
                # Don't revisit chains we've already seen, unless the target
                # sequence number is higher than last time.
                if ts <= visited_chains.get(tc, 0):
                    continue

                if ss <= seq:
                    if tc == target_chain:
                        if target_seq <= ts:
                            return True
                    else:
                        search.append((tc, ts))

    return False

def test_simple(self, batched: bool) -> None:
    """Test that the example in `docs/auth_chain_difference_algorithm.md`
    works.
    """

    event_factory = self.hs.get_event_builder_factory()
    bob = "@creator:test"
    alice = "@alice:test"
    charlie = "@charlie:test"
    room_id = "!room:test"

    # Ensure that we have a rooms entry so that we generate the chain index.
    self.get_success(
        self.store.store_room(
            room_id=room_id,
            room_creator_user_id="",
            is_public=True,
            room_version=RoomVersions.V6,
        )
    )

    create = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Create,
                "state_key": "",
                "sender": bob,
                "room_id": room_id,
                "content": {"tag": "create"},
            },
        ).build(prev_event_ids=[], auth_event_ids=[])
    )

    bob_join = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Member,
                "state_key": bob,
                "sender": bob,
                "room_id": room_id,
                "content": {"tag": "bob_join"},
            },
        ).build(prev_event_ids=[], auth_event_ids=[create.event_id])
    )

    power = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.PowerLevels,
                "state_key": "",
                "sender": bob,
                "room_id": room_id,
                "content": {"tag": "power"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[create.event_id, bob_join.event_id],
        )
    )

    alice_invite = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Member,
                "state_key": alice,
                "sender": bob,
                "room_id": room_id,
                "content": {"tag": "alice_invite"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[create.event_id, bob_join.event_id, power.event_id],
        )
    )

    alice_join = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Member,
                "state_key": alice,
                "sender": alice,
                "room_id": room_id,
                "content": {"tag": "alice_join"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[create.event_id, alice_invite.event_id, power.event_id],
        )
    )

    power_2 = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.PowerLevels,
                "state_key": "",
                "sender": bob,
                "room_id": room_id,
                "content": {"tag": "power_2"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[create.event_id, bob_join.event_id, power.event_id],
        )
    )

    bob_join_2 = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Member,
                "state_key": bob,
                "sender": bob,
                "room_id": room_id,
                "content": {"tag": "bob_join_2"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[create.event_id, bob_join.event_id, power.event_id],
        )
    )

    alice_join2 = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Member,
                "state_key": alice,
                "sender": alice,
                "room_id": room_id,
                "content": {"tag": "alice_join2"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[
                create.event_id,
                alice_join.event_id,
                power_2.event_id,
            ],
        )
    )

    charlie_invite = self.get_success(
        event_factory.for_room_version(
            RoomVersions.V6,
            {
                "type": EventTypes.Member,
                "state_key": charlie,
                "sender": alice,
                "room_id": room_id,
                "content": {"tag": "charlie_invite"},
            },
        ).build(
            prev_event_ids=[],
            auth_event_ids=[
                create.event_id,
                alice_join2.event_id,
                power_2.event_id,
            ],
        )
    )

    events = [
        create,
        bob_join,
        power,
        alice_invite,
        alice_join,
        bob_join_2,
        power_2,
        alice_join2,
        charlie_invite,
    ]

    expected_links = [
        (bob_join, create),
        (power, bob_join),
        (alice_invite, power),
        (bob_join_2, power),
        (alice_join2, power_2),
        (charlie_invite, alice_join2),
    ]

    # We either persist as a batch or one-by-one depending on test
    # parameter.
    if batched:
        self.persist(events)
    else:
        for event in events:
            self.persist([event])

    chain_map, link_map = self.fetch_chains(events)

    # Check that the expected links and only the expected links have been
    # added.
    event_map = {e.event_id: e for e in events}
    reverse_chain_map = {v: event_map[k] for k, v in chain_map.items()}

    self.maxDiff = None
    self.assertCountEqual(
        expected_links,
        [
            (reverse_chain_map[(s1, s2)], reverse_chain_map[(t1, t2)])
            for s1, s2, t1, t2 in link_map.get_additions()
        ],
    )

    # Test that everything can reach the create event, but the create event
    # can't reach anything.
    for event in events[1:]:
        self.assertTrue(
            link_map.exists_path_from(
                chain_map[event.event_id], chain_map[create.event_id]
            ),
        )

        self.assertFalse(
            link_map.exists_path_from(
                chain_map[create.event_id],
                chain_map[event.event_id],
            ),
        )

