def post(self, request, slug, service):
    project_id = request.data.get("project_id", False)

    if not project_id:
        return Response(
            {"error": "Project ID is required"},
            status=status.HTTP_400_BAD_REQUEST,
        )

    workspace = Workspace.objects.get(slug=slug)

    if service == "github":
        data = request.data.get("data", False)
        metadata = request.data.get("metadata", False)
        config = request.data.get("config", False)
        if not data or not metadata or not config:
            return Response(
                {"error": "Data, config and metadata are required"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        api_token = APIToken.objects.filter(
            user=request.user, workspace=workspace
        ).first()
        if api_token is None:
            api_token = APIToken.objects.create(
                user=request.user,
                label="Importer",
                workspace=workspace,
            )

        importer = Importer.objects.create(
            service=service,
            project_id=project_id,
            status="queued",
            initiated_by=request.user,
            data=data,
            metadata=metadata,
            token=api_token,
            config=config,
            created_by=request.user,
            updated_by=request.user,
        )

        service_importer.delay(service, importer.id)
        serializer = ImporterSerializer(importer)
        return Response(serializer.data, status=status.HTTP_201_CREATED)

    if service == "jira":
        data = request.data.get("data", False)
        metadata = request.data.get("metadata", False)
        config = request.data.get("config", False)

        cloud_hostname = metadata.get("cloud_hostname", False)

        if not cloud_hostname:
            return Response(
                {"error": "Cloud hostname is required"},
                status=status.HTTP_400_BAD_REQUEST,
            )

        if not is_allowed_hostname(cloud_hostname):
            return Response(
                {"error": "Hostname is not a valid hostname."},
                status=status.HTTP_400_BAD_REQUEST,
            )

        if not data or not metadata:
            return Response(
                {"error": "Data, config and metadata are required"},
                status=status.HTTP_400_BAD_REQUEST,
            )
        api_token = APIToken.objects.filter(
            user=request.user, workspace=workspace
        ).first()
        if api_token is None:
            api_token = APIToken.objects.create(
                user=request.user,
                label="Importer",
                workspace=workspace,
            )

        importer = Importer.objects.create(
            service=service,
            project_id=project_id,
            status="queued",
            initiated_by=request.user,
            data=data,
            metadata=metadata,
            token=api_token,
            config=config,
            created_by=request.user,
            updated_by=request.user,
        )

        service_importer.delay(service, importer.id)
        serializer = ImporterSerializer(importer)
        return Response(serializer.data, status=status.HTTP_201_CREATED)

    return Response(
        {"error": "Servivce not supported yet"},
        status=status.HTTP_400_BAD_REQUEST,
    )

